using System.Reflection;
using Elevant.Api.Configuration;
using Microsoft.OpenApi;

namespace Elevant.Api.OpenApi;

/// <summary>Configures the versioned OpenAPI document generated by Swashbuckle.</summary>
public static class SwaggerConfiguration
{
    /// <summary>Adds the v1 document and a future HTTP Bearer security scheme.</summary>
    public static IServiceCollection AddElevantOpenApi(this IServiceCollection services)
    {
        ArgumentNullException.ThrowIfNull(services);

        services.AddSwaggerGen(options =>
        {
            options.SwaggerDoc(ApiConfiguration.ApiVersion, new OpenApiInfo
            {
                Title = "Elevant API",
                Version = ApiConfiguration.ApiVersion,
                Description = "Versioned HTTP API for the Elevant platform.",
            });

            options.AddSecurityDefinition("Bearer", new OpenApiSecurityScheme
            {
                Type = SecuritySchemeType.Http,
                Scheme = "bearer",
                BearerFormat = "JWT",
                Description = "Future JWT authorization header. Authentication is not enabled by this scaffold.",
            });

            options.DocInclusionPredicate((documentName, description) =>
                description.GroupName is null ||
                string.Equals(description.GroupName, documentName, StringComparison.OrdinalIgnoreCase));

            var xmlFileName = $"{Assembly.GetExecutingAssembly().GetName().Name}.xml";
            var xmlPath = Path.Combine(AppContext.BaseDirectory, xmlFileName);
            if (File.Exists(xmlPath))
            {
                options.IncludeXmlComments(xmlPath);
            }
        });

        return services;
    }
}
